import React from 'react';

interface FormattedTextProps {
  text?: string;
  className?: string;
  as?: 'p' | 'span' | 'div';
}

/**
 * Renders text respecting:
 * 1. Line breaks generated by pressing Enter in CMS textareas (\n)
 * 2. Explicit <br>, <br/>, or <br /> tags typed by the user
 */
export const FormattedText: React.FC<FormattedTextProps> = ({ 
  text = '', 
  className = '', 
  as = 'span' 
}) => {
  if (!text) return null;

  // Normalize any literal <br>, <br/>, <br /> into real \n
  const normalized = text.replace(/<br\s*\/?>/gi, '\n');
  const lines = normalized.split('\n');

  const content = lines.map((line, idx) => (
    <React.Fragment key={idx}>
      {line}
      {idx < lines.length - 1 && <br />}
    </React.Fragment>
  ));

  const Tag = as;
  return (
    <Tag className={`whitespace-pre-line ${className}`}>
      {content}
    </Tag>
  );
};
